"""About, FAQ, implementation ledger, research, and glossary."""

import json
from pathlib import Path

import streamlit as st

from loanpilot import config
from loanpilot.ledger import ledger_frame
from loanpilot.theme import render_disclaimer, render_header

_FAQ = [
    (
        "Is this real?",
        "This is a working software demonstration for a fictional bank. The people, "
        "applications, documents, bureau responses and KYC responses are synthetic.",
    ),
    (
        "Where does data come from?",
        "The sample portfolio is generated by a deterministic local seed. A guided "
        "application can also save synthetic form inputs and uploaded demo PDFs.",
    ),
    (
        "Can the AI approve a loan?",
        "No. Deterministic policy code produces a recommendation. A human reviewer "
        "must make the decision before a case can be sanctioned.",
    ),
    (
        "Is this RBI compliant?",
        "No compliance claim is made. The KFS is illustrative. Any real lending "
        "journey needs legal, compliance, security and RBI-guideline review.",
    ),
    (
        "What about bias?",
        "Synthetic data cannot establish fair outcomes. A real deployment would "
        "need testing across groups, data-quality controls and ongoing monitoring.",
    ),
    (
        "What happens if the AI is wrong?",
        "The recommendation is evidence-linked and handed to a human. Reviewers "
        "can make a different decision, with a written reason recorded for an override.",
    ),
    (
        "How does sign-in work?",
        "Demo-grade sign-in: no MFA or single sign-on; session ends when the browser page is refreshed.",
    ),
]

_GLOSSARY = [
    ("FOIR", "Fixed Obligations-to-Income Ratio: monthly existing and proposed EMIs divided by monthly income."),
    ("DPD", "Days Past Due: how many days a repayment arrived after its due date."),
    ("KFS", "Key Fact Statement: a summary of loan costs and terms. This demo preview is illustrative."),
    ("CERSAI", "Central Registry of Securitisation Asset Reconstruction and Security Interest of India; shown as not applicable for this unsecured demo loan."),
    ("CIBIL", "A well-known Indian credit information company; all bureau results here are simulated."),
    ("KYC", "Know Your Customer checks used to verify identity; this demo response is simulated."),
    ("Lakehouse", "A shared data foundation that stores original records and prepared data for analysis."),
    ("Agent", "Software that follows a defined workflow and calls tools; it is not an independent loan decision-maker."),
]


def _render_optional_markdown(path: Path, empty_message: str) -> None:
    """Render a project-rooted optional Markdown file or a friendly placeholder."""
    if path.is_file():
        st.markdown(path.read_text(encoding="utf-8"))
    else:
        st.info(empty_message)


def render() -> None:
    """Render the complete reference page as audience-friendly tabs."""
    render_disclaimer()
    render_header(
        "About & FAQ",
        "What this demonstration can show, what it cannot claim, and where its assumptions come from.",
        "REFERENCE  /  PROJECT NOTES",
    )
    tabs = st.tabs(
        [
            "About",
            "FAQ",
            "Real vs simulated",
            "Research note",
            "AI usage log",
            "Assumptions",
            "Glossary",
            "Contact",
        ]
    )
    with tabs[0]:
        st.subheader("Aarambh Bank · LoanPilot")
        st.info(
            "Demonstration with synthetic data. Not a real bank system or credit decision."
        )
        st.write(
            "LoanPilot is a presales point-of-view demo for a fictional mid-sized "
            "Indian bank. It shows a personal-loan journey from application intake "
            "through evidence review and a human decision."
        )
        st.warning(
            "Not a real bank system, credit decision, loan offer or regulatory-compliance claim."
        )
        st.markdown(
            "- Sample cases and uploaded demo documents are synthetic.\n"
            "- Policy checks run in deterministic code.\n"
            "- AI recommendations go to Human Review; AI cannot sanction.\n"
            "- Disbursement records are simulated. No funds move."
        )
    with tabs[1]:
        st.subheader("Frequently asked questions")
        for question, answer in _FAQ:
            with st.expander(question):
                st.write(answer)
    with tabs[2]:
        st.subheader("Implementation ledger")
        st.caption(
            "Component status is loaded from the project ledger. Conditional Gemini "
            "status is resolved from persisted live assessment traces."
        )
        st.dataframe(ledger_frame(), width="stretch", hide_index=True)
    with tabs[3]:
        st.subheader("Research basis")
        _render_optional_markdown(
            config.DOCS_DIR / "research_note.md",
            "Research note to be added.",
        )
    with tabs[4]:
        st.subheader("AI usage log")
        _render_optional_markdown(
            config.DOCS_DIR / "ai_usage_log.md",
            "AI usage log to be added.",
        )
    with tabs[5]:
        st.subheader("Assumptions")
        with config.ILLUSTRATIVE_METRICS_PATH.open(encoding="utf-8") as metrics_file:
            metrics = json.load(metrics_file)
        st.markdown(
            "- The portfolio and all identifiers are synthetic.\n"
            "- Bureau and KYC results are mock responses.\n"
            "- Policy thresholds and prices are illustrative demo settings.\n"
            "- Gemini is optional and cannot change deterministic outcomes.\n"
            "- Demo-grade sign-in: no MFA or single sign-on; session ends when the browser page is refreshed.\n"
            "- Disbursement is simulated; generated PDFs contain synthetic content."
        )
        st.markdown("#### Illustrative turnaround inputs")
        st.write(
            f"Baseline: {float(metrics['baseline_turnaround_days']):g} days. "
            f"Demo assumption: {float(metrics['demo_turnaround_days']):g} days."
        )
        st.caption(metrics["source"])
        st.markdown("#### Limitations")
        st.write(
            "This prototype is not a production credit platform. It does not provide "
            "identity verification, live bureau access, a secure customer channel, "
            "automated alerts or regulatory approval."
        )
    with tabs[6]:
        st.subheader("Glossary")
        st.dataframe(
            [{"Term": term, "Plain-English meaning": meaning} for term, meaning in _GLOSSARY],
            width="stretch",
            hide_index=True,
        )
    with tabs[7]:
        st.subheader("Demo contact")
        st.info("Fictional demo contact — not a customer service channel.")
        st.write("Aarambh Bank · LoanPilot demonstration team")
        st.write("Email: loanpilot-demo@example.invalid")
        st.write("Telephone: +91 00000 00000")
